<script setup>
import { ref,onMounted,onBeforeUnmount } from 'vue'
import { getJSON } from '../api'
import { fmtTime } from '../status'
const state=ref(null),error=ref('');let timer
const names={database:'业务数据库',redis:'实时缓存',mqtt:'机器人消息连接',storage:'巡检图片存储',workers:'后台处理'}
const workerNames={delivery:'指令交付与复检收尾',watchdog:'任务超时检查',vision_0:'图片分析 1',vision_1:'图片分析 2'}
const labels={ok:'正常',down:'需要处理',degraded:'需要关注'}
async function load(){try{state.value=await getJSON('/api/ops/status');error.value=''}catch(e){error.value=e.message}}
onMounted(()=>{load();timer=setInterval(load,10000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><div class="eyebrow">SERVICE OPERATIONS</div><h1>运行状态</h1><p>查看服务依赖、后台处理与积压情况，快速定位故障。</p></div><el-button @click="load">↻ 刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="state"><div class="ops-banner surface"><div><span :class="['ops-dot',state.status]"></span><strong>{{ state.ready?'服务已就绪':'服务尚未就绪' }}</strong><small>{{ state.status==='degraded'?'部分功能需要关注':state.ready?'各关键依赖与后台处理可用':'请检查下方异常项目' }}</small></div><time>{{ fmtTime(state.checked_at) }}</time></div><div class="dependency-grid"><article v-for="(c,key) in state.components" :key="key" class="surface"><small>{{ names[key] }}</small><b :class="c.status">{{ labels[c.status] }}</b><p>{{ c.message || (c.status==='ok'?'连接与处理状态正常':'暂时不可用，请检查服务日志') }}</p><span v-if="c.free_mb!=null">剩余 {{ (c.free_mb/1024).toFixed(1) }} GB</span></article></div><div class="queue-grid"><section class="surface"><h2>指令交付</h2><strong>{{ state.queues.commands?.pending||0 }} <small>条待确认</small></strong><p>最早等待 {{ state.queues.oldest_command_seconds||0 }} 秒</p><small>发送成功与机器人接单分别记录；等待确认期间会自动重发。</small></section><section class="surface"><h2>图片分析</h2><strong>{{ (state.queues.vision?.pending||0)+(state.queues.vision?.processing||0) }} <small>张处理中</small></strong><p>已完成 {{ state.queues.vision?.succeeded||0 }} · 历史失败 {{ state.queues.vision?.failed||0 }}</p><small>最早等待 {{ state.queues.oldest_analysis_seconds||0 }} 秒。历史失败请在检测记录中复核。</small></section></div><section class="surface workers-panel"><h2>后台处理状态</h2><div v-for="(w,key) in state.workers" :key="key"><b>{{ workerNames[key] }}</b><span :class="w.status">{{ labels[w.status] }}</span><small>{{ w.age_seconds==null?'尚未开始':w.age_seconds+' 秒前更新' }}</small></div></section><section class="surface ops-notes"><h2>设备与模型配置</h2><p v-for="r in state.robots" :key="r.robot_id">{{ r.robot_id }} <span :class="r.online?'ok':'degraded'">{{ r.online?'在线':'无实时遥测' }}</span></p><p>{{ state.model_configured?'模型连接信息已配置':'模型连接信息尚未配置' }}</p><small>此页不会请求付费模型。配置存在不代表上游模型服务当前可用，实际调用结果请查看检测记录。</small></section></template></template>
<style scoped>.ops-banner{display:flex;justify-content:space-between;gap:15px;align-items:center;padding:22px;margin-bottom:20px}.ops-banner strong{font-size:17px}.ops-banner small{display:block;margin:10px 0 0 16px;color:#90a080;font-size:11px}.ops-banner time{font-size:11px;color:#90a080}.ops-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#7aa371;margin-right:10px}.ops-dot.down{background:#c56d55}.ops-dot.degraded{background:#b89758}.dependency-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:15px;margin-bottom:22px}.dependency-grid article{padding:20px}.dependency-grid article>small{display:block;color:#8d9c7d;font-size:11px}.dependency-grid b{display:block;font-size:20px;font-weight:550;margin:16px 0}.dependency-grid p,.dependency-grid span{font-size:10px;color:#9aa68c;line-height:1.8}.ok{color:#518366}.down{color:#b76650}.degraded{color:#a7884c}.queue-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:22px}.queue-grid section,.workers-panel,.ops-notes{padding:24px}.queue-grid h2,.workers-panel h2,.ops-notes h2{font-size:14px;margin:0 0 20px}.queue-grid strong{font-size:30px;color:#527349}.queue-grid strong small{font-size:11px;font-weight:400}.queue-grid p,.ops-notes p{font-size:12px;color:#819574}.queue-grid section>small,.ops-notes small{font-size:10px;color:#9aa88b;line-height:1.8}.workers-panel{margin-bottom:22px}.workers-panel>div{display:flex;gap:24px;align-items:center;padding:14px 0;border-top:1px solid #edf0e6;font-size:12px}.workers-panel b{font-weight:500;flex:1}.workers-panel small{color:#9aa78d;font-size:10px}.ops-notes span{margin-left:15px}@media(max-width:1150px){.dependency-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:750px){.dependency-grid{grid-template-columns:1fr 1fr}.queue-grid{grid-template-columns:1fr}.ops-banner{align-items:start;flex-direction:column}}
</style>
